insert into public.card_catalog (bank_name, card_name, network, default_benefits, default_annual_fee, card_color_theme)
values
('HDFC Bank', 'HDFC Regalia Credit Card', 'Visa', '[{"title":"Domestic Airport Lounge Access","category":"lounge","description":"2 complimentary domestic airport lounge visits per quarter (8/year). IMPORTANT: Requires minimum spend of ₹1,00,000 in the preceding calendar quarter to qualify. Zero visits credited if spend threshold not met. Minimum spend of ₹1,00,000 in preceding calendar quarter required. Check eligibility on HDFC Netbanking before visiting lounge. (2 visits/quarter)","value_estimate":null},{"title":"International Lounge via Priority Pass","category":"lounge","description":"6 complimentary international lounge visits per year via Priority Pass (combined for primary + add-on cardholder). Priority Pass membership must be activated separately after completing 4 retail transactions. Complete minimum 4 retail transactions before applying for Priority Pass. 6 visits shared between primary and add-on cardholder. Usage inside India is chargeable. (6 visits/year)","value_estimate":null},{"title":"Air Accident Insurance Cover","category":"other","description":"Personal accident death cover of ₹1 crore in case of air accidental death. Card must have been used at least once in preceding 60 days for cover to be active. Card must be active with at least one transaction in preceding 60 days. Claim must be raised within 130 days of incident. (₹1 crore cover)","value_estimate":null},{"title":"4 Reward Points per ₹150 Spent","category":"shopping","description":"Earn 4 reward points on every ₹150 of retail spend. Bonus 10,000 points on ₹5L annual spend, additional 5,000 points on ₹8L annual spend. 1 point ≈ ₹0.50 when redeemed on SmartBuy for flights/hotels. Excludes fuel, wallet loads, and EMI transactions. Points expire in 2 years. (4 pts/₹150)","value_estimate":null},{"title":"Fuel Surcharge Waiver","category":"fuel","description":"1% fuel surcharge waiver at all fuel stations across India on transactions between ₹400 and ₹5,000. Valid on transactions between ₹400 and ₹5,000 only. (1% waiver)","value_estimate":null}]'::jsonb, 2500, 'indigo'),
('HDFC Bank', 'HDFC Regalia Gold Credit Card', 'Visa', '[{"title":"Domestic Airport Lounge Access","category":"lounge","description":"3 complimentary domestic airport lounge visits per quarter (12/year). Requires minimum spend of ₹60,000 in the preceding calendar quarter. Zero visits if spend threshold not met. Minimum ₹60,000 spend in preceding calendar quarter required to unlock quarterly lounge benefit. (3 visits/quarter)","value_estimate":null},{"title":"Complimentary Swiggy One Membership","category":"shopping","description":"Complimentary Swiggy One membership as welcome benefit. Includes free deliveries and exclusive restaurant discounts. Welcome benefit — activate within stated validity period after card issuance. (~₹1,299/yr value)","value_estimate":1299},{"title":"Complimentary MMT Black Gold Membership","category":"travel","description":"Complimentary MakeMyTrip Black Gold membership as welcome benefit. Includes exclusive hotel and flight discounts. Welcome benefit — activate within stated validity period after card issuance. (~₹2,999/yr value)","value_estimate":2999},{"title":"Air Accident Insurance Cover","category":"other","description":"Personal accident death cover of ₹1 crore in case of air accidental death. Card must be active with recent transaction before incident. (₹1 crore cover)","value_estimate":null},{"title":"4 Reward Points per ₹150 Spent","category":"shopping","description":"Earn 4 reward points on every ₹150 retail spend. 5X points on select brands via SmartBuy. Quarterly milestone: ₹1,500 voucher on ₹1.5L quarterly spend. Excludes fuel, wallet loads, EMI. 5X on select SmartBuy merchants only. (4 pts/₹150)","value_estimate":null}]'::jsonb, 2500, 'indigo'),
('HDFC Bank', 'HDFC Diners Black Credit Card', 'Diners', '[{"title":"Unlimited Domestic + International Lounge Access","category":"lounge","description":"Unlimited complimentary access to 1,000+ domestic and international airport lounges worldwide for primary cardholder. No quarterly or annual cap. Note: This card has been discontinued by HDFC (replaced by Diners Black Metal). Existing cardholders continue to receive benefits. (Unlimited)","value_estimate":null},{"title":"6 Complimentary Golf Games per Quarter","category":"entertainment","description":"6 complimentary golf games per quarter at leading golf courses across India and internationally. Subject to golf course availability. Advance booking required. (6 games/quarter)","value_estimate":null},{"title":"Air Accident Insurance Cover","category":"other","description":"Air accidental death cover of ₹2 crore. Emergency overseas hospitalization cover of ₹50 lakh. Baggage delay cover up to ₹50,000. Credit liability cover ₹9 lakh. Card must be active with recent transaction. Multiple covers bundled — verify each with HDFC ERGO. (₹2 crore air accident cover)","value_estimate":null},{"title":"5 Reward Points per ₹150 + 10X on SmartBuy","category":"shopping","description":"Earn 5 reward points per ₹150 on all retail spends (3.3% reward rate). 10X points on SmartBuy portal. Complimentary annual memberships: Amazon Prime, Club Marriott, Swiggy One, Times Prime (on ₹8L annual spend). Monthly vouchers worth ₹500 from leading brands on ₹80,000 monthly spend. Insurance spends capped at 5,000 pts/month. Grocery capped at 2,000 pts/month. Annual fee waived on ₹8L annual spend. (5 pts/₹150 (3.3% rate))","value_estimate":null}]'::jsonb, 10000, 'indigo'),
('HDFC Bank', 'HDFC Millennia Credit Card', 'Mastercard', '[{"title":"5% Cashback on Top Shopping Apps","category":"shopping","description":"5% cashback on Amazon, Flipkart, Myntra, Swiggy, Zomato, BookMyShow, Cult.fit, and other partner apps. Capped at ₹1,000 cashback per statement cycle across all partners combined. Capped at ₹1,000 CashPoints per statement cycle. Excludes EMI transactions. (5% back (cap ₹1,000/mo))","value_estimate":1000},{"title":"1% Cashback on All Other Spends","category":"shopping","description":"1% cashback on all spends not covered by the 5% partner category. Excludes fuel, wallet loads, and EMI transactions. (1% back)","value_estimate":null},{"title":"Domestic Airport Lounge Access","category":"lounge","description":"1 complimentary domestic airport lounge visit per quarter. Check minimum spend requirement on HDFC portal — may require quarterly spend threshold. (1 visit/quarter)","value_estimate":null},{"title":"Fuel Surcharge Waiver","category":"fuel","description":"1% fuel surcharge waiver at all fuel stations on transactions between ₹400 and ₹5,000. Valid on transactions between ₹400 and ₹5,000 only. (1% waiver)","value_estimate":null}]'::jsonb, 1000, 'indigo')
